#!/usr/bin/env node
// Bundles WeavAI_FINAL_FIXED.html (the single-file demo) into a JS module
// the Expo app can import and feed to react-native-webview. Run via
// `npm run prebundle` — also runs automatically before `expo start`.

const fs = require('fs');
const path = require('path');

const SOURCE = path.resolve(__dirname, '..', '..', '..', 'WeavAI_FINAL_FIXED.html');
const OUT    = path.resolve(__dirname, '..', 'src', 'htmlBundle.js');

if (!fs.existsSync(SOURCE)) {
  console.error('[bundle-html] missing source:', SOURCE);
  process.exit(1);
}

let html = fs.readFileSync(SOURCE, 'utf8');

// Patch the API base URL to the Railway production backend so the WebView
// talks to the real backend when running natively (the demo defaults to
// localhost:8000 when running standalone in a browser).
const apiShim = `
<script>
  window.WEAVAI_API_BASE_URL = 'https://backend-api-production-243d.up.railway.app';
  window.WEAVAI_PLATFORM     = 'native-expo';
</script>
`;
html = html.replace('</head>', apiShim + '</head>');

fs.mkdirSync(path.dirname(OUT), { recursive: true });
// JSON.stringify produces a valid double-quoted JS string literal that
// safely escapes backticks, ${}, backslashes, and newlines — so template
// literals inside the demo's <script> blocks survive the round trip.
fs.writeFileSync(
  OUT,
  `// Auto-generated by scripts/bundle-html.js — DO NOT EDIT BY HAND.\n` +
  `// Source: WeavAI_FINAL_FIXED.html (${html.length} chars, ${(html.length/1024).toFixed(1)} KB)\n` +
  `export default ${JSON.stringify(html)};\n`
);
console.log(`[bundle-html] wrote ${path.relative(process.cwd(), OUT)} — ${(html.length/1024).toFixed(1)} KB`);
